import numpy as np
import time


def _C(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * float(np.max(np.convolve(h, h))) / (s * s)


def _refine(h, N_target, deadline):
    """Coordinate-descent style refinement on heights, keeping N fixed."""
    h = np.asarray(h, dtype=float).copy()
    N = len(h)
    best = _C(h)
    # scale-invariant: normalize sum
    h /= h.sum()
    step = 0.05
    while time.process_time() < deadline and step > 1e-4:
        improved = False
        for i in range(N):
            if time.process_time() >= deadline:
                break
            base = h[i]
            for mult in (1.0 + step, 1.0 - step, 1.0 + 0.5 * step, 1.0 - 0.5 * step):
                h[i] = base * mult
                if h[i] < 0:
                    h[i] = 0.0
                h /= h.sum()
                c = _C(h)
                if c < best - 1e-12:
                    best = c
                    base = h[i]
                    improved = True
                else:
                    h[i] = base
                    h /= h.sum()
        if not improved:
            step *= 0.5
    return h, best


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    # Start from a smooth bump (triangle-ish) which has low C, or improve the given start.
    if start is not None:
        h = np.asarray(start, dtype=float).copy()
        if h.sum() <= 0 or np.any(h < 0) or len(h) > 30000:
            h = None
        else:
            h = h / h.sum()
    else:
        h = None

    if h is None:
        # triangle on [-1/4,1/4]: linear up then down, approximates the extremal shape
        N = 400
        x = np.linspace(-1, 1, N)
        h = 1.0 - np.abs(x)
        h = np.maximum(h, 1e-3)
        h /= h.sum()

    best_h, best_c = h.copy(), _C(h)

    # Try a few candidate shapes / resolutions, refine each, keep best.
    candidates = [h]
    for N in (100, 200, 600, 1200):
        if time.process_time() >= deadline:
            break
        x = np.linspace(-1, 1, N)
        cand = np.maximum(1.0 - np.abs(x), 1e-3)
        cand /= cand.sum()
        candidates.append(cand)

    for cand in candidates:
        if time.process_time() >= deadline:
            break
        rh, rc = _refine(cand, len(cand), deadline)
        if rc < best_c:
            best_c, best_h = rc, rh

    # Final polish on the best
    if time.process_time() < deadline:
        best_h, best_c = _refine(best_h, len(best_h), deadline)

    print("final C ~", best_c, "N", len(best_h))
    return best_h

