def _resample(x, N):
    """Resample a 1-D array to length N by linear interpolation."""
    x = np.asarray(x, dtype=float)
    if x.size == N:
        return x.copy()
    m = x.size
    t = np.linspace(0.0, m - 1, N)
    return np.interp(t, np.arange(m), x)


def construct(budget_seconds, start):
    t0 = time.process_time()
    budget = budget_seconds - 2.0  # margin

    if start is not None:
        h = np.asarray(start, dtype=float).copy()
        if h.ndim != 1 or h.size == 0 or h.sum() <= 0 or not np.all(np.isfinite(h)):
            h = np.ones(50)
