        N = 200
        x = np.linspace(-1, 1, N)
        h = np.maximum(0.0, 1.0 - np.abs(x)) + 1e-3

    h = np.maximum(h, 0.0)
    N = h.size
    best = h.copy()
    bestC = _C(best)

    def try_update(h, C, idx, factor):
        old = h[idx]
        h[idx] = old * factor
        Cn = _C(h)
        if Cn < C:
            return Cn
        h[idx] = old
        return C

    rng = np.random.default_rng(12345)

    # Phase 1: multiplicative coordinate sweeps.
    step = 0.9
    while time.process_time() - t0 < budget * 0.4:
        improved = False
        order = rng.permutation(N)
        for i in order:
            if time.process_time() - t0 >= budget * 0.4:
                break
            for f in (1.0 + step, 1.0 / (1.0 + step)):
                Cn = try_update(h, bestC, i, f)
                if Cn < bestC:
                    bestC = Cn
                    best = h.copy()
                    improved = True
                    break
        if not improved:
            step *= 0.5
            if step < 1e-4:
                break

    # Phase 2: random pairwise multiplicative perturbations.
    while time.process_time() - t0 < budget * 0.7:
        improved = False
        for _ in range(min(2000, 50 * N)):
            if time.process_time() - t0 >= budget * 0.7:
                break
            i = rng.integers(N)
            j = rng.integers(N)
            if i == j:
                continue
            fi = 1.0 + rng.uniform(-0.2, 0.2)
            fj = 1.0 + rng.uniform(-0.2, 0.2)
            oi, oj = h[i], h[j]
            h[i] = oi * fi
            h[j] = oj * fj
            Cn = _C(h)
            if Cn < bestC:
                bestC = Cn
                best = h.copy()
                improved = True
            else:
                h[i], h[j] = oi, oj
        if not improved:
            h = best.copy()
            h = np.maximum(h * (1.0 + rng.normal(0, 0.01, size=N)), 0.0)
            Cn = _C(h)
            if Cn < bestC:
                bestC = Cn
                best = h.copy()
            else:
                h = best.copy()

    # Phase 3 (new): resample to a larger grid and refine there.
    # A finer grid can realise a slightly better shape; resampling preserves C roughly.
    while time.process_time() - t0 < budget:
        cur_n = best.size
        # Grow grid size (up to 30000).
        new_n = min(30000, max(cur_n + 1, int(cur_n * 1.5)))
        if new_n <= cur_n:
            break
        cand = _resample(best, new_n)
        cand = np.maximum(cand, 0.0)
        Cn = _C(cand)
        if Cn < bestC:
            bestC = Cn
            best = cand.copy()
        else:
            # Even if resampling slightly worsens C, refine on the finer grid
            # starting from it, which often recovers and improves.
            h = cand.copy()
            N = new_n
            # quick coordinate sweep on the finer grid
            step = 0.3
            local_best = h.copy()
            local_C = Cn
            for _ in range(3):
                order = rng.permutation(N)
                for i in order:
                    if time.process_time() - t0 >= budget:
                        break
                    for f in (1.0 + step, 1.0 / (1.0 + step)):
                        Cn2 = try_update(h, local_C, i, f)
                        if Cn2 < local_C:
                            local_C = Cn2
                            local_best = h.copy()
                            break
                step *= 0.5
                if time.process_time() - t0 >= budget:
                    break
            if local_C < bestC:
                bestC = local_C
                best = local_best.copy()
            else:
                break
        if time.process_time() - t0 >= budget:
            break

    return np.asarray(best, dtype=float)

