        s = x.sum()
        if s <= 0:
            return np.inf
        return 2.0 * N * np.max(np.convolve(x, x)) / (s * s)

    best = h.copy()
    bestC = C_of(best)

    rng = np.random.default_rng(20240101)

    def elapsed():
        return time.process_time() - t0

    # --- Phase 1: coordinate-wise multiplicative + additive sweeps ---
    step_mul = 0.5
    step_add = 0.05 * (best.max() if best.max() > 0 else 1.0)
    while elapsed() < budget * 0.35:
        improved = False
        order = rng.permutation(N)
        for i in order:
            if elapsed() >= budget * 0.35:
