                    h[i] = nv
                    c = C_of(h)
                    if c < bestC - 1e-12:
                        bestC = c; best = h.copy(); improved = True
                        break
                    else:
                        h[i] = old
        if not improved:
            step_mul *= 0.6
            step_add *= 0.6
            if step_mul < 1e-3:
                break

    # --- Phase 2: pairwise perturbations, restart from best ---
    h = best.copy()
    while elapsed() < budget:
        improved = False
        trials = min(4000, 60 * N)
        for _ in range(trials):
            if elapsed() >= budget:
