import numpy as np
import time


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 0.6

    def C_of(h):
        s = h.sum()
        N = len(h)
        if s <= 0 or N == 0:
            return np.inf
        return 2.0 * N * np.max(np.convolve(h, h)) / (s * s)

    if start is not None:
        h = np.asarray(start, dtype=float).copy()
        if h.ndim != 1 or h.size == 0 or not np.all(np.isfinite(h)) or h.sum() <= 0:
            h = np.ones(50)
    else:
        h = np.ones(50)
    h = np.maximum(h, 0.0)
    if h.sum() <= 0:
        h = np.ones(50)

    def resample(h, newN):
        N = len(h)
        if N == newN:
            return h.copy()
        cum = np.concatenate([[0.0], np.cumsum(h)])
        edges = np.linspace(0.0, N, newN + 1)
        out = np.empty(newN)
        for j in range(newN):
            a, b = edges[j], edges[j + 1]
            ia, ib = int(np.floor(a)), int(np.floor(b))
            if ia == ib:
                out[j] = h[ia] * (b - a)
            else:
                val = h[ia] * (ia + 1 - a)
                if ib > ia + 1:
                    val += (cum[ib] - cum[ia + 1])
                if ib < N:
                    val += h[ib] * (b - ib)
                else:
                    val += h[N - 1] * (b - N)
                out[j] = val
        out = np.maximum(out, 0.0)
        if out.sum() > 0:
            out *= h.sum() / out.sum()
        return out

    # --- Core optimizer: coordinate descent with incremental conv updates ---
    def optimize(h_in, end_time):
        h = np.maximum(np.asarray(h_in, dtype=float), 0.0)
        s = h.sum()
        if s <= 0:
            return np.ones(len(h)), np.inf
        h = h * (1.0 / s)
        N = len(h)
        L = 2 * N - 1
        conv = np.convolve(h, h)
        best = h.copy()
        bestC = 2.0 * N * conv.max()

        def try_update(i, nv):
            old = h[i]
            d = nv - old
            if d == 0.0 or nv < 0:
                return None
            sc = s + d
            if sc <= 0:
                return None
            c = conv.copy()
            a = 2.0 * d
            end = min(i + N, L)
            c[i:end] += a * h[0:end - i]
            c[2 * i] += d * d
            M = c.max()
            return (2.0 * N * M / (sc * sc), c, sc, nv)

        def active_pivots(tol):
            M = conv.max()
            idx = np.where(conv >= M * (1.0 - tol))[0]
            cand = np.zeros(N, dtype=bool)
            w = np.zeros(N)
            for k in idx:
                lo = max(0, k - (N - 1))
                hi = min(N - 1, k)
                rng = np.arange(lo, hi + 1)
                cand[lo:hi + 1] = True
                w[lo:hi + 1] += h[k - rng]
            piv = np.where(cand)[0]
            return piv[np.argsort(-w[piv])]

        scale_sets = [
            [1.0 + c for c in (0.30, -0.30, 0.18, -0.18, 0.10, -0.10, 0.05, -0.05)],
            [1.0 + c for c in (0.06, -0.06, 0.03, -0.03, 0.015, -0.015)],
            [1.0 + c for c in (0.02, -0.02, 0.01, -0.01, 0.005, -0.005)],
            [1.0 + c for c in (0.004, -0.004, 0.002, -0.002, 0.001, -0.001)],
            [1.0 + c for c in (0.0005, -0.0005, 0.0002, -0.0002, 0.0001, -0.0001)],
            [1.0 + c for c in (5e-5, -5e-5, 2e-5, -2e-5, 1e-5, -1e-5)],
        ]

        for scales in scale_sets:
            if time.process_time() >= end_time:
                break
            while time.process_time() < end_time:
                improved = False
                order = active_pivots(1e-10)
                for i in order:
                    if time.process_time() >= end_time:
                        break
                    old = h[i]
                    best_res = None
                    for f in scales:
                        nv = old * f
                        r = try_update(i, nv)
                        if r is not None and r[0] < bestC - 1e-17:
                            if best_res is None or r[0] < best_res[0]:
                                best_res = r
                    if best_res is not None:
                        bestC, conv, s, nv = best_res
                        h[i] = nv
                        best = h.copy()
                        improved = True
                if not improved:
                    break

        # Additive fine polish
        while time.process_time() < end_time:
            improved = False
            order = active_pivots(1e-12)
            for i in order:
                if time.process_time() >= end_time:
                    break
                old = h[i]
                best_res = None
                for d in (1e-4, -1e-4, 1e-5, -1e-5, 1e-6, -1e-6, 1e-7, -1e-7):
                    nv = old + d
                    if nv < 0:
                        nv = 0.0
                    r = try_update(i, nv)
                    if r is not None and r[0] < bestC - 1e-16:
                        if best_res is None or r[0] < best_res[0]:
                            best_res = r
                if best_res is not None:
                    bestC, conv, s, nv = best_res
                    h[i] = nv
                    best = h.copy()
                    improved = True
            if not improved:
                break
        return best, bestC

    # --- Candidate N sweep ---
    N0 = len(h)
    candidates = set([N0])
    for dN in (-4, -3, -2, -1, 1, 2, 3, 4, 6, -6, 8, -8, 12, -12):
        n = N0 + dN
        if 4 <= n <= 30000:
            candidates.add(n)
    if N0 < 20:
        for n in (30, 50, 80, 100):
            candidates.add(n)
    candidates = sorted(candidates)

    scored = []
    for n in candidates:
        hc = resample(h, n) if n != N0 else h.copy()
        if hc.sum() <= 0:
            continue
        c = C_of(hc)
        scored.append((c, n, hc))
    scored.sort(key=lambda x: x[0])

    best_overall = h.copy()
    best_overall_C = C_of(h)

    # Optimize top few candidates, giving larger share to the best
    top = scored[:4]
    weights = [1.0, 0.5, 0.3, 0.2]
    wsum = sum(weights[:len(top)])

    for k, (c0, n, hc) in enumerate(top):
        now = time.process_time()
        if now >= deadline:
            break
        frac = weights[k] / wsum
        end_t = min(now + max(deadline - now, 0.0) * frac, deadline)
        h_opt, _ = optimize(hc, end_t)
        c_opt = C_of(h_opt)
        if c_opt < best_overall_C:
            best_overall_C = c_opt
            best_overall = h_opt.copy()
        wsum -= weights[k]

    # Final polish
    now = time.process_time()
    if now < deadline - 0.05:
        h_fin, _ = optimize(best_overall, deadline)
        c_fin = C_of(h_fin)
        if c_fin < best_overall_C:
            best_overall = h_fin
            best_overall_C = c_fin

    return np.asarray(best_overall, dtype=float)

