import time


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 0.5

    if start is not None:
        h = np.asarray(start, dtype=float).copy()
        if h.ndim != 1 or h.size == 0 or not np.all(np.isfinite(h)) or h.sum() <= 0:
            h = np.ones(50)
    else:
        h = np.ones(50)

    h = np.maximum(h, 0.0)
    if h.sum() <= 0:
        h = np.ones(50)

    def C_of(h):
        s = h.sum()
        N = len(h)
        if s <= 0 or N == 0:
            return np.inf
        return 2.0 * N * np.max(np.convolve(h, h)) / (s * s)

    def resample(h, newN):
        N = len(h)
        if N == newN:
            return h.copy()
        cum = np.concatenate([[0.0], np.cumsum(h)])
        edges = np.linspace(0.0, N, newN + 1)
        out = np.empty(newN)
        for j in range(newN):
            a, b = edges[j], edges[j + 1]
            ia, ib = int(np.floor(a)), int(np.floor(b))
            if ia == ib:
                out[j] = h[ia] * (b - a)
            else:
                val = h[ia] * (ia + 1 - a)
                if ib > ia + 1:
                    val += (cum[ib] - cum[ia + 1])
                if ib < N:
                    val += h[ib] * (b - ib)
                else:
                    val += h[N - 1] * (b - N)
                out[j] = val
        out = np.maximum(out, 0.0)
        if out.sum() > 0:
            out *= h.sum() / out.sum()
        return out

    # --- Optimizer: coordinate descent with incremental conv updates ---
    # We minimize C = 2N * M / s^2 where M = max(conv), s = sum(h).
    # Since scaling h by a constant leaves C invariant, we can also try
    # to directly reduce M while holding s fixed via pairwise moves.
    # The main win here: vectorized coordinate perturbation search with
    # exact incremental conv update, and a "peak-tracking" active set.
    def optimize(h_in, end_time):
        h = np.maximum(np.asarray(h_in, dtype=float), 0.0)
        s = h.sum()
        if s <= 0:
            return np.ones(len(h)), np.inf
        h = h / s
        s = 1.0
        N = len(h)
        L = 2 * N - 1
        conv = np.convolve(h, h)
        best = h.copy()
        bestC = 2.0 * N * conv.max()

        def apply_update(h, conv, s, i, nv):
            old = h[i]
            d = nv - old
            if d == 0.0 or nv < 0:
                return None
            sc = s + d
            if sc <= 0:
