        def active_indices(conv, N, thresh):
            M = conv.max()
            idx = np.where(conv >= M * (1.0 - thresh))[0]
            mask = np.zeros(N, dtype=bool)
            for k in idx:
                lo = max(0, k - (N - 1))
                hi = min(N - 1, k)
                mask[lo:hi + 1] = True
            return np.where(mask)[0]

