        hc = hc / hc.sum()
        scored.append((C_of(hc), n, hc))
    scored.sort(key=lambda x: x[0])

    best_overall = h.copy()
    best_overall_C = C_of(best_overall)

    # Optimize top few candidates, giving most time to the best
    top = scored[:4]
