        return 2.0 * N * np.max(np.convolve(h, h)) / (s * s)

    def resample(h, newN):
        N = len(h)
        if N == newN:
            return h.copy()
        cum = np.concatenate([[0.0], np.cumsum(h)])
        edges = np.linspace(0.0, N, newN + 1)
        out = np.empty(newN)
        for j in range(newN):
            a, b = edges[j], edges[j + 1]
            ia, ib = int(np.floor(a)), int(np.floor(b))
            if ia == ib:
                out[j] = h[ia] * (b - a)
            else:
                val = h[ia] * (ia + 1 - a)
                if ib > ia + 1:
                    val += (cum[ib] - cum[ia + 1])
                if ib < N:
                    val += h[ib] * (b - ib)
                else:
                    val += h[N - 1] * (b - N)
                out[j] = val
        out = np.maximum(out, 0.0)
        if out.sum() > 0:
            out *= h.sum() / out.sum()
        return out

    # Key change: optimize the actual invariant quantity directly by
    # tracking the set of active peak knots and doing Newton-like updates
    # on small linear sub-problems.  Also use FFT-free direct conv updates.
    def optimize(h, end_time):
        h = np.maximum(np.asarray(h, dtype=float), 0.0)
        s = h.sum()
        if s <= 0:
            return np.ones(len(h)), np.inf
        h = h / s
        N = len(h)
        L = 2 * N - 1
        conv = np.convolve(h, h)
        best = h.copy()
        bestC = 2.0 * N * conv.max()

        def try_update(h, conv, s, i, nv):
            old = h[i]
            d = nv - old
            if d == 0.0 or nv < 0:
                return None
            sc = s + d
            if sc <= 0:
                return None
            c = conv.copy()
            a = 2.0 * d
            end = min(i + N, L)
            c[i:end] += a * h[0:end - i]
            c[2 * i] += d * d
            M = c.max()
            return (2.0 * N * M / (sc * sc), c, sc, nv)

