            w = np.zeros(N)
            for k in idx:
                lo = max(0, k - (N - 1))
                hi = min(N - 1, k)
                cand_i[lo:hi + 1] = True
                w[lo:hi + 1] += h[k - np.arange(lo, hi + 1)]
