    else:
        h = np.ones(50)
    h = np.maximum(h, 0.0)
    if h.sum() <= 0:
        h = np.ones(50)

    def C_of(hv):
        s = hv.sum()
        if s <= 0:
            return np.inf
        return 2.0 * len(hv) * float(np.max(np.convolve(hv, hv))) / (s * s)

    # ---- Mass-preserving resample of a step function ----
    def resample(hv, newN):
        N = len(hv)
        if N == newN:
            return hv.copy()
        cum = np.concatenate([[0.0], np.cumsum(hv)])
        edges = np.linspace(0.0, N, newN + 1)
        out = np.empty(newN)
        for j in range(newN):
            a, b = edges[j], edges[j + 1]
            ia, ib = int(np.floor(a)), int(np.floor(b))
            if ia == ib:
                out[j] = hv[ia] * (b - a)
            else:
                v = hv[ia] * (ia + 1 - a)
                if ib > ia + 1:
                    v += cum[ib] - cum[ia + 1]
                if ib < N:
                    v += hv[ib] * (b - ib)
                else:
                    v += hv[N - 1] * (b - N)
                out[j] = v
        out = np.maximum(out, 0.0)
        s = out.sum()
        if s > 0:
            out *= hv.sum() / s
        return out

    # ---- Optimizer: coordinate descent on autoconvolution peak ----
    # Key idea: we only care about the MAX. Instead of trying to push
    # the peak down everywhere, we track the peak knots and adjust
    # entries that contribute to them. We use a random-restart / multi
    # perturbation strategy to escape local minima by adding mass in
    # directions that flatten the peak.
    def optimize(hv, end_time):
        hv = np.maximum(np.asarray(hv, dtype=float).copy(), 0.0)
        s = hv.sum()
        if s <= 0:
            return np.ones(len(hv)), np.inf
        hv /= s
        N = len(hv)
        L = 2 * N - 1
        conv = np.convolve(hv, hv)
        best = hv.copy()
        bestC = 2.0 * N * float(conv.max())

        def try_update(hv, conv, s, i, nv):
            old = hv[i]
            d = nv - old
            if d == 0.0 or nv < 0:
                return None
            sc = s + d
            if sc <= 0:
                return None
            c = conv.copy()
            a = 2.0 * d
            end = min(i + N, L)
            c[i:end] += a * hv[0:end - i]
            c[2 * i] += d * d
            M = float(c.max())
            return (2.0 * N * M / (sc * sc), c, sc, nv)

        def active_pivots(conv, hv):
            M = float(conv.max())
            idx = np.where(conv >= M * (1.0 - 1e-12))[0]
            cand = np.zeros(N, dtype=bool)
            for k in idx:
                lo = max(0, k - (N - 1))
                hi = min(N - 1, k)
                cand[lo:hi + 1] = True
            return np.where(cand)[0]

        scale_sets = [
            [1.0 + c for c in (0.30, -0.30, 0.15, -0.15, 0.07, -0.07)],
            [1.0 + c for c in (0.05, -0.05, 0.02, -0.02, 0.01, -0.01)],
            [1.0 + c for c in (0.006, -0.006, 0.003, -0.003, 0.0015, -0.0015)],
            [1.0 + c for c in (0.0008, -0.0008, 0.0004, -0.0004, 0.0002, -0.0002)],
            [1.0 + c for c in (0.0001, -0.0001, 5e-5, -5e-5, 2e-5, -2e-5)],
        ]

        for scales in scale_sets:
            while time.process_time() < end_time:
                improved = False
                pivots = active_pivots(conv, hv)
                for i in pivots:
