                        if nv < 0 or nv == old:
                            continue
                        r = try_update(hv, conv, s, i, nv)
                        if r is not None and r[0] < bestC - 1e-17:
                            if best_res is None or r[0] < best_res[0]:
                                best_res = r
                    if best_res is not None:
                        bestC, conv, s, nv = best_res
                        hv[i] = nv
                        if bestC < 2.0 * N * float(np.max(np.convolve(best, best))) / (best.sum() ** 2):
                            best = hv.copy()
                        improved = True
                if not improved:
                    break

