        h = np.maximum(np.asarray(h, dtype=float), 0.0)
        s = h.sum()
        if s <= 0:
            return np.ones(len(h)), np.inf
        h = h / s
        N = len(h)
        L = 2 * N - 1
        conv = np.convolve(h, h)
        best = h.copy()
        bestC = 2.0 * N * conv.max()
        s_cur = 1.0

        scales = [0.1, -0.1, 0.05, -0.05, 0.02, -0.02, 0.01, -0.01,
                  0.005, -0.005, 0.002, -0.002, 0.001, -0.001,
                  0.0005, -0.0005, 0.0002, -0.0002, 0.0001, -0.0001]

        while time.process_time() < end_time:
            improved = False
            M = conv.max()
            idx = np.where(conv >= M * (1.0 - 1e-9))[0]
            cand = np.zeros(N, dtype=bool)
            for k in idx:
                lo = max(0, k - (N - 1))
                hi = min(N - 1, k)
                cand[lo:hi + 1] = True
            pivots = np.where(cand)[0]
            if len(pivots) == 0:
                break
            for i in pivots:
                if time.process_time() >= end_time:
                    break
                old = h[i]
                best_res = None
                best_C_here = bestC
                for sc in scales:
                    delta = old * sc if old > 1e-12 else sc
                    nv = old + delta
                    if nv < 0:
                        nv = 0.0
                        delta = nv - old
                    if delta == 0.0:
