            for j in range(n):
                a, b = edges[j], edges[j + 1]
                ia, ib = int(np.floor(a)), int(np.floor(b))
                if ia == ib:
                    out[j] = hc[ia] * (b - a)
                else:
                    val = hc[ia] * (ia + 1 - a)
                    if ib > ia + 1:
                        val += (cum[ib] - cum[ia + 1])
                    if ib < N0:
                        val += hc[ib] * (b - ib)
                    else:
                        val += hc[N0 - 1] * (b - N0)
                    out[j] = val
            out = np.maximum(out, 0.0)
            if out.sum() <= 0:
                continue
            out = out / out.sum()
            h2, _ = optimize(out, deadline - 0.03)
            c2 = C_of(h2)
            if c2 < best_overall_C:
                best_overall = h2
                best_overall_C = c2

