        for j in range(newN):
            a, b = edges[j], edges[j + 1]
            ia, ib = int(np.floor(a)), int(np.floor(b))
            if ia == ib:
                out[j] = h[ia] * (b - a)
            else:
                val = h[ia] * (ia + 1 - a)
                if ib > ia + 1:
                    val += (cum[ib] - cum[ia + 1])
                if ib < N:
                    val += h[ib] * (b - ib)
                else:
                    val += h[N - 1] * (b - N)
                out[j] = val
        out = np.maximum(out, 0.0)
        if out.sum() > 0:
            out *= h.sum() / out.sum()
        return out

