import numpy as np
import time


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 0.5

    if start is not None:
        h = np.asarray(start, dtype=float).copy()
        if h.ndim != 1 or h.size == 0 or not np.all(np.isfinite(h)) or h.sum() <= 0:
            h = np.ones(50)
    else:
        h = np.ones(50)
    h = np.maximum(h, 0.0)
    if h.sum() <= 0:
        h = np.ones(50)

    def C_of(h):
        s = h.sum()
        N = len(h)
        if s <= 0 or N == 0:
            return np.inf
        return 2.0 * N * np.max(np.convolve(h, h)) / (s * s)

    def resample(h, newN):
        N = len(h)
        if N == newN:
            return h.copy()
        cum = np.concatenate([[0.0], np.cumsum(h)])
        edges = np.linspace(0.0, N, newN + 1)
        out = np.empty(newN)
        for j in range(newN):
            a, b = edges[j], edges[j + 1]
            ia, ib = int(np.floor(a)), int(np.floor(b))
            if ia == ib:
                out[j] = h[ia] * (b - a)
            else:
                val = h[ia] * (ia + 1 - a)
                if ib > ia + 1:
                    val += (cum[ib] - cum[ia + 1])
                if ib < N:
                    val += h[ib] * (b - ib)
                else:
                    val += h[N - 1] * (b - N)
                out[j] = val
        out = np.maximum(out, 0.0)
        if out.sum() > 0:
            out *= h.sum() / out.sum()
        return out

    def optimize(h, end_time):
        h = np.maximum(np.asarray(h, dtype=float), 0.0)
        s = h.sum()
        if s <= 0:
            return np.ones(len(h)), np.inf
        h = h / s
        N = len(h)
        L = 2 * N - 1
        conv = np.convolve(h, h)
        best = h.copy()
        bestC = 2.0 * N * conv.max()

        def try_update(h, conv, s, i, nv):
            old = h[i]
            d = nv - old
            if d == 0.0 or nv < 0:
                return None
            sc = s + d
            if sc <= 0:
                return None
            c = conv.copy()
            a = 2.0 * d
            end = min(i + N, L)
            c[i:end] += a * h[0:end - i]
            c[2 * i] += d * d
            M = c.max()
            return (2.0 * N * M / (sc * sc), c, sc, nv)

        def gather_candidates(h, conv):
            M = conv.max()
            idx = np.where(conv >= M * (1.0 - 1e-9))[0]
            cand_i = np.zeros(N, dtype=bool)
            w = np.zeros(N)
            for k in idx:
                lo = max(0, k - (N - 1))
                hi = min(N - 1, k)
                cand_i[lo:hi + 1] = True
                w[lo:hi + 1] += h[k - np.arange(lo, hi + 1)]
            pivots = np.where(cand_i)[0]
            order = pivots[np.argsort(-w[pivots])]
            return order

        scale_sets = [
            [1.0 + c for c in (0.3, -0.3, 0.2, -0.2, 0.12, -0.12, 0.07, -0.07, 0.04, -0.04)],
            [1.0 + c for c in (0.05, -0.05, 0.03, -0.03, 0.015, -0.015, 0.008, -0.008)],
            [1.0 + c for c in (0.01, -0.01, 0.005, -0.005, 0.002, -0.002)],
            [1.0 + c for c in (0.001, -0.001, 0.0005, -0.0005, 0.0002, -0.0002)],
        ]

        def sweep_multi(h, conv, s, bestC, best, end_time, scales):
            while time.process_time() < end_time:
                improved = False
                order = gather_candidates(h, conv)
                for i in order:
                    if time.process_time() >= end_time:
                        break
                    old = h[i]
                    best_res = None
                    for f in scales:
                        nv = old * f
                        if nv < 0 or nv == old:
                            continue
                        r = try_update(h, conv, s, i, nv)
                        if r is not None and r[0] < bestC - 1e-17:
                            if best_res is None or r[0] < best_res[0]:
                                best_res = r
                    if best_res is not None:
                        bestC, conv, s, nv = best_res
                        h[i] = nv
                        best = h.copy()
                        improved = True
                if not improved:
                    return h, conv, s, best, bestC
            return h, conv, s, best, bestC

        for scales in scale_sets:
            if time.process_time() >= end_time:
                break
            h, conv, s, best, bestC = sweep_multi(h, conv, s, bestC, best, end_time, scales)

        add_sets = [
            (1e-3, -1e-3, 5e-4, -5e-4),
            (1e-4, -1e-4, 5e-5, -5e-5),
            (1e-5, -1e-5, 1e-6, -1e-6),
            (1e-7, -1e-7),
        ]
        for adds in add_sets:
            if time.process_time() >= end_time:
                break
            while time.process_time() < end_time:
                improved = False
                order = gather_candidates(h, conv)
                for i in order:
                    if time.process_time() >= end_time:
                        break
                    old = h[i]
                    best_res = None
                    for d in adds:
                        nv = old + d
                        if nv < 0:
                            nv = 0.0
                        if nv == old:
                            continue
                        r = try_update(h, conv, s, i, nv)
                        if r is not None and r[0] < bestC - 1e-18:
                            if best_res is None or r[0] < best_res[0]:
                                best_res = r
                    if best_res is not None:
                        bestC, conv, s, nv = best_res
                        h[i] = nv
                        best = h.copy()
                        improved = True
                if not improved:
                    break

        return best, bestC

    # --- Joint pair-coordinate descent: move two heights simultaneously ---
    # This escapes single-coordinate local minima and can reduce the peak more.
    def optimize_pairs(h, end_time):
        h = np.maximum(np.asarray(h, dtype=float), 0.0)
        s = h.sum()
        if s <= 0:
            return np.ones(len(h)), np.inf
        h = h / s
        N = len(h)
        conv = np.convolve(h, h)
        best = h.copy()
        bestC = 2.0 * N * conv.max()

        def conv_update(conv, h, i, di, N, L):
            end = min(i + N, L)
            conv[i:end] += 2.0 * di * h[0:end - i]
            conv[2 * i] += di * di

        M = conv.max()
        idx = np.where(conv >= M * (1.0 - 1e-6))[0]
        cand_i = np.zeros(N, dtype=bool)
        for k in idx:
            lo = max(0, k - (N - 1))
            hi = min(N - 1, k)
            cand_i[lo:hi + 1] = True
        pivots = np.where(cand_i)[0]
        if len(pivots) > 40:
            # keep the most influential ones
            w = np.zeros(N)
            for k in idx:
                lo = max(0, k - (N - 1))
                hi = min(N - 1, k)
                w[lo:hi + 1] += h[k - np.arange(lo, hi + 1)]
            pivots = pivots[np.argsort(-w[pivots])][:40]

        step = 0.02
        while time.process_time() < end_time and step > 1e-7:
            improved = False
            for ii in range(len(pivots)):
                if time.process_time() >= end_time:
                    break
                i = pivots[ii]
                for jj in range(ii + 1, len(pivots)):
                    j = pivots[jj]
                    hi_i, hi_j = h[i], h[j]
                    best_res = None
                    for di in (-step, step):
                        for dj in (-step, step):
                            ni = hi_i + di
                            nj = hi_j + dj
                            if ni < 0 or nj < 0:
                                continue
                            ds = di + dj
                            sc = s + ds
                            if sc <= 0:
                                continue
                            c = conv.copy()
                            conv_update(c, h, i, di, N, 2 * N - 1)
                            conv_update(c, h, j, dj, N, 2 * N - 1)
                            # correct double-count of i==j term is zero here
                            Mv = c.max()
                            val = 2.0 * N * Mv / (sc * sc)
                            if val < bestC - 1e-18:
                                if best_res is None or val < best_res[0]:
                                    best_res = (val, c, sc, ni, nj)
                    if best_res is not None:
                        bestC, conv, s, ni, nj = best_res
                        h[i] = ni
                        h[j] = nj
                        best = h.copy()
                        improved = True
            if not improved:
                step *= 0.5
            else:
                # mild re-expansion to allow larger moves
                step = min(step * 1.5, 0.05)

        return best, bestC

    N0 = len(h)
    candidates = set([N0])
    for dN in (-8, -5, -3, -2, -1, 1, 2, 3, 5, 8, 12, -12):
        n = N0 + dN
        if 4 <= n <= 30000:
            candidates.add(n)
    if N0 < 10:
        for n in (15, 20, 30, 40, 50, 60, 80, 100):
            candidates.add(n)
    for n in (30, 40, 45, 50, 55, 60, 70, 80):
        candidates.add(n)
    candidates = sorted(candidates)

    scored = []
    for n in candidates:
        hc = resample(h, n) if n != N0 else h.copy()
        if hc.sum() <= 0:
            continue
        hc = hc / hc.sum()
        c = C_of(hc)
        scored.append((c, n, hc))
    scored.sort(key=lambda x: x[0])

    if not scored:
        return np.asarray(h, dtype=float)

    best_overall = None
    best_overall_C = np.inf

    top = scored[:4]
    weights = [1.0, 0.7, 0.5, 0.35]
    wsum = sum(weights[:len(top)])

    for k, (c0, n, hc) in enumerate(top):
        now = time.process_time()
        if now >= deadline - 0.05:
            break
        frac = weights[k] / wsum
        end_t = now + max(deadline - now, 0.0) * frac * 0.7
        end_t = min(end_t, deadline)
        h_opt, c_opt = optimize(hc, end_t)
        c_opt = C_of(h_opt)
        if c_opt < best_overall_C:
            best_overall_C = c_opt
            best_overall = h_opt.copy()
        wsum -= weights[k]

    if best_overall is None:
        best_overall = h
        best_overall_C = C_of(best_overall)

    # --- Pair-coordinate polish on best (substantial new move) ---
    now = time.process_time()
    if now < deadline - 0.05:
        h_pair, c_pair = optimize_pairs(best_overall, deadline - 0.02)
        c_pair = C_of(h_pair)
        if c_pair < best_overall_C:
            best_overall = h_pair
            best_overall_C = c_pair

    # Final single-coordinate polish
    now = time.process_time()
    if now < deadline - 0.02:
        h_fin, c_fin = optimize(best_overall, deadline - 0.005)
        c_fin = C_of(h_fin)
        if c_fin < best_overall_C:
            best_overall = h_fin
            best_overall_C = c_fin

    return np.asarray(best_overall, dtype=float)

