            else:
                val = h[ia] * (ia + 1 - a)
                if ib > ia + 1:
                    val += (cum[ib] - cum[ia + 1])
                if ib < N:
                    val += h[ib] * (b - ib)
                out[j] = val
        out = np.maximum(out, 0.0)
        if out.sum() > 0:
            out *= h.sum() / out.sum()
        return out

    # Smooth surrogate: C_smooth(h) = 2N * softmax_beta(conv) / (sum h)^2
    # Use scipy L-BFGS-B with analytic-ish gradient via finite differences on
    # a reduced parameter set (log-h).  This escapes plateaus much faster than
    # coordinate sweeps and reaches tighter local minima.
    def optimize_smooth(h, end_time, beta_scale=200.0):
        h = np.maximum(np.asarray(h, dtype=float), 0.0)
        s = h.sum()
        if s <= 0:
            return np.ones(len(h)), np.inf
        h = h / s
        N = len(h)

        def unpack(x):
            z = x - x.max()
            e = np.exp(z)
            return e / e.sum()

        def Cval(x):
            hh = unpack(x)
            c = np.convolve(hh, hh)
            return 2.0 * N * c.max()

        def Cval_smooth(x, beta):
            hh = unpack(x)
            c = np.convolve(hh, hh)
            m = c.max()
            w = np.exp(beta * (c - m))
            sm = (c * w).sum() / w.sum()
            return 2.0 * N * sm

        best = h.copy()
        bestC = Cval(np.log(h + 1e-12))
        x = np.log(h + 1e-12)

        betas = [beta_scale, beta_scale * 5, beta_scale * 25, beta_scale * 125]
        for beta in betas:
            if time.process_time() >= end_time:
                break
            def f(xx):
                return Cval_smooth(xx, beta)
            try:
                res = minimize(f, x, method='L-BFGS-B',
                               options={'maxiter': 200, 'ftol': 1e-14, 'gtol': 1e-12})
                x = res.x
            except Exception:
                break
            cand = unpack(x)
            cc = Cval(x)
            if cc < bestC:
                bestC = cc
                best = cand.copy()
