        if N == newN:
            return h.copy()
        cum = np.concatenate([[0.0], np.cumsum(h)])
        edges = np.linspace(0.0, N, newN + 1)
        out = np.empty(newN)
        for j in range(newN):
            a, b = edges[j], edges[j + 1]
            ia, ib = int(np.floor(a)), int(np.floor(b))
            if ia == ib:
                out[j] = h[ia] * (b - a)
            else:
                val = h[ia] * (ia + 1 - a)
                if ib > ia + 1:
                    val += (cum[ib] - cum[ia + 1])
                if ib < N:
                    val += h[ib] * (b - ib)
                else:
                    val += h[N - 1] * (b - N)
                out[j] = val
        out = np.maximum(out, 0.0)
        if out.sum() > 0:
            out *= h.sum() / out.sum()
        return out

    def optimize(h, end_time):
        h = np.maximum(np.asarray(h, dtype=float), 0.0)
        s = h.sum()
        if s <= 0:
            return np.ones(len(h)), np.inf
        h = h / s
        N = len(h)
        L = 2 * N - 1
        conv = np.convolve(h, h)
        best = h.copy()
        bestC = 2.0 * N * conv.max()

        def active_knots(conv, tol):
            M = conv.max()
            return np.where(conv >= M * (1.0 - tol))[0]

        def try_update(h, conv, s, i, nv):
            old = h[i]
            d = nv - old
            if d == 0.0 or nv < 0:
                return None
            sc = s + d
            if sc <= 0:
                return None
            c = conv.copy()
            a = 2.0 * d
            end = min(i + N, L)
            c[i:end] += a * h[0:end - i]
            c[2 * i] += d * d
            M = c.max()
            return (2.0 * N * M / (sc * sc), c, sc, nv)

        def gather_candidates(h, conv, tol):
            idx = active_knots(conv, tol)
            cand_i = np.zeros(N, dtype=bool)
            w = np.zeros(N)
            for k in idx:
                lo = max(0, k - (N - 1))
                hi = min(N - 1, k)
                cand_i[lo:hi + 1] = True
                w[lo:hi + 1] += h[k - np.arange(lo, hi + 1)]
            pivots = np.where(cand_i)[0]
            order = pivots[np.argsort(-w[pivots])]
            return order

        def pair_sweep(h, conv, s, bestC, best, end_time):
            order = gather_candidates(h, conv, 1e-5)
            step = 0.02
            while time.process_time() < end_time and step > 1e-7:
                improved = False
                for i in order:
                    if time.process_time() >= end_time:
                        break
                    for j in (i - 1, i + 1):
                        if j < 0 or j >= N:
                            continue
                        if h[i] <= 0:
                            continue
                        delta = h[i] * step
                        if delta <= 0:
                            continue
                        old_i, old_j = h[i], h[j]
                        h[i] = old_i - delta
                        h[j] = old_j + delta
                        c = np.convolve(h, h)
                        M = c.max()
                        Cv = 2.0 * N * M / (s * s)
                        if Cv < bestC - 1e-16:
                            bestC = Cv
                            conv = c
                            best = h.copy()
                            improved = True
                        else:
                            h[i] = old_i
                            h[j] = old_j
                if not improved:
                    step *= 0.5
            return h, conv, s, best, bestC

        scale_sets = [
            [1.0 + c for c in (0.3, -0.3, 0.2, -0.2, 0.12, -0.12, 0.07, -0.07, 0.04, -0.04)],
            [1.0 + c for c in (0.05, -0.05, 0.03, -0.03, 0.015, -0.015, 0.008, -0.008)],
            [1.0 + c for c in (0.01, -0.01, 0.005, -0.005, 0.002, -0.002)],
            [1.0 + c for c in (0.001, -0.001, 0.0005, -0.0005, 0.0002, -0.0002)],
        ]

        def sweep_multi(h, conv, s, bestC, best, end_time, scales):
            while time.process_time() < end_time:
                improved = False
                order = gather_candidates(h, conv, 1e-7)
                for i in order:
                    if time.process_time() >= end_time:
                        break
                    old = h[i]
                    best_res = None
                    for f in scales:
                        nv = old * f
                        if nv < 0 or nv == old:
                            continue
                        r = try_update(h, conv, s, i, nv)
                        if r is not None and r[0] < bestC - 1e-17:
                            if best_res is None or r[0] < best_res[0]:
                                best_res = r
                    if best_res is not None:
                        bestC, conv, s, nv = best_res
                        h[i] = nv
                        best = h.copy()
                        improved = True
                if not improved:
                    return h, conv, s, best, bestC
            return h, conv, s, best, bestC

        for scales in scale_sets:
            if time.process_time() >= end_time:
                break
            h, conv, s, best, bestC = sweep_multi(h, conv, s, bestC, best, end_time, scales)

        add_sets = [
            (1e-3, -1e-3, 5e-4, -5e-4),
            (1e-4, -1e-4, 5e-5, -5e-5),
            (1e-5, -1e-5, 1e-6, -1e-6),
            (1e-7, -1e-7),
        ]
        for adds in add_sets:
            if time.process_time() >= end_time:
                break
            while time.process_time() < end_time:
                improved = False
                order = gather_candidates(h, conv, 1e-7)
                for i in order:
                    if time.process_time() >= end_time:
                        break
                    old = h[i]
                    best_res = None
                    for d in adds:
                        nv = old + d
                        if nv < 0:
                            nv = 0.0
                        if nv == old:
                            continue
                        r = try_update(h, conv, s, i, nv)
                        if r is not None and r[0] < bestC - 1e-18:
                            if best_res is None or r[0] < best_res[0]:
                                best_res = r
                    if best_res is not None:
                        bestC, conv, s, nv = best_res
                        h[i] = nv
                        best = h.copy()
                        improved = True
                if not improved:
                    break

        if time.process_time() < end_time:
            h, conv, s, best, bestC = pair_sweep(h, conv, s, bestC, best, end_time)

        return best, bestC

    N0 = len(h0)
    candidates = set([N0])
    for dN in (-2, -1, 1, 2, 3, -3, 5, -5):
        n = N0 + dN
        if 4 <= n <= 30000:
            candidates.add(n)
    for n in (40, 50, 60, 70):
        candidates.add(n)
    candidates = sorted(candidates)

    scored = []
    for n in candidates:
        hc = resample(h0, n) if n != N0 else h0.copy()
        if hc.sum() <= 0:
            continue
        hc = hc / hc.sum()
        c = C_of(hc)
        scored.append((c, n, hc))
    scored.sort(key=lambda x: x[0])

    if not scored:
        return np.asarray(h0, dtype=float)

    best_overall = None
    best_overall_C = np.inf

    top = scored[:2]
    weights = [1.0, 0.55]
    wsum = sum(weights[:len(top)])

    for k, (c0, n, hc) in enumerate(top):
        now = time.process_time()
        if now >= deadline - 0.05:
            break
        frac = weights[k] / wsum
        end_t = now + max(deadline - now, 0.0) * frac
        end_t = min(end_t, deadline)
        h_opt, c_opt = optimize(hc, end_t)
        c_opt = C_of(h_opt)
        if c_opt < best_overall_C:
            best_overall_C = c_opt
            best_overall = h_opt.copy()
        wsum -= weights[k]

    if best_overall is None:
        best_overall = h0
        best_overall_C = C_of(h0)

    now = time.process_time()
    if now < deadline - 0.05:
        h_fin, c_fin = optimize(best_overall, deadline)
        c_fin = C_of(h_fin)
        if c_fin < best_overall_C:
            best_overall = h_fin
            best_overall_C = c_fin

