    ladder.append(fine)

    # Also try a few nearby Ns at the end
    for d in (N0 + 1, N0 - 1, N0 + 2, N0 - 2, N0 + 5, N0 - 5):
        if 4 <= d <= 30000:
            ladder.append(d)

    # Allocate time: first coarse ladder, then fine polish
    seen = set()
    uniq_ladder = []
    for n in ladder:
        if n not in seen and 4 <= n <= 30000:
            seen.add(n)
            uniq_ladder.append(n)

    # Sort so we start at N0, go up, then come back
    up = sorted([n for n in uniq_ladder if n >= N0])
    down = sorted([n for n in uniq_ladder if n < N0], reverse=True)
    order = up + down

    total = len(order)
    for idx, n in enumerate(order):
        now = time.process_time()
        if now >= deadline - 0.05:
            break
        remaining = deadline - now
        end_t = now + remaining / max(1, (total - idx))
        h_new, c_new = refine_at_N(best_overall, n, end_t)
        if c_new < best_overall_C:
            best_overall = h_new
            best_overall_C = c_new

    # Final polish at the current best N with all remaining time
    now = time.process_time()
    if now < deadline - 0.05:
        h_fin, c_fin = polish(best_overall, deadline)
        c_fin = C_of(h_fin)
        if c_fin < best_overall_C:
            best_overall = h_fin
            best_overall_C = c_fin

    return np.asarray(best_overall, dtype=float)

import numpy as np
import time
from scipy.optimize import minimize


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 0.7

    if start is not None:
        h0 = np.asarray(start, dtype=float).copy()
        if h0.ndim != 1 or h0.size == 0 or not np.all(np.isfinite(h0)) or h0.sum() <= 0:
            h0 = np.ones(50)
    else:
        h0 = np.ones(50)
    h0 = np.maximum(h0, 0.0)
    if h0.sum() <= 0:
        h0 = np.ones(50)

    def C_of(h):
        s = h.sum()
        N = len(h)
        if s <= 0 or N == 0:
            return np.inf
        return 2.0 * N * np.max(np.convolve(h, h)) / (s * s)

    def resample(h, newN):
        N = len(h)
        if N == newN:
            return h.copy()
        cum = np.concatenate([[0.0], np.cumsum(h)])
        edges = np.linspace(0.0, N, newN + 1)
        out = np.empty(newN)
        for j in range(newN):
            a, b = edges[j], edges[j + 1]
            ia, ib = int(np.floor(a)), int(np.floor(b))
            if ia == ib:
                out[j] = h[ia] * (b - a)
            else:
                val = h[ia] * (ia + 1 - a)
                if ib > ia + 1:
                    val += (cum[ib] - cum[ia + 1])
                if ib < N:
                    val += h[ib] * (b - ib)
                out[j] = val
        out = np.maximum(out, 0.0)
        if out.sum() > 0:
            out *= h.sum() / out.sum()
        return out

    def exact_descent(h, end_time, rounds=200):
        h = np.maximum(np.asarray(h, dtype=float), 0.0)
        s = h.sum()
        if s <= 0:
            return np.ones(len(h)), np.inf
        h = h / s
        N = len(h)
        conv = np.convolve(h, h)
        bestC = 2.0 * N * conv.max()
        best = h.copy()
        step = 0.02
        for _ in range(rounds):
            if time.process_time() >= end_time:
                break
            M = conv.max()
            active = np.where(conv >= M - 1e-9 * max(M, 1e-30))[0]
            g = np.zeros(N)
            for k in active:
                lo = max(0, k - (N - 1))
                hi = min(N - 1, k)
                idx = np.arange(lo, hi + 1)
                g[idx] += 2.0 * h[k - idx]
            g /= len(active)
            g -= g.mean()
            gn = np.linalg.norm(g)
            if gn < 1e-15:
                break
            g /= gn
            improved = False
            for _ls in range(40):
                hn = h - step * g
                hn = np.maximum(hn, 0.0)
                sn = hn.sum()
                if sn <= 0:
                    step *= 0.5
                    continue
                hn /= sn
                cn = np.convolve(hn, hn)
                Cc = 2.0 * N * cn.max()
                if Cc < bestC - 1e-15:
                    h = hn
                    conv = cn
                    bestC = Cc
                    best = h.copy()
                    improved = True
                    step *= 1.5
                    break
                else:
                    step *= 0.5
            if not improved:
                step *= 0.7
                if step < 1e-12:
                    break
        return best, bestC

    def optimize_smooth(h, end_time, beta_scale=200.0):
        h = np.maximum(np.asarray(h, dtype=float), 0.0)
        s = h.sum()
        if s <= 0:
            return np.ones(len(h)), np.inf
        h = h / s
        N = len(h)

        def unpack(x):
            z = x - x.max()
            e = np.exp(z)
            return e / e.sum()

        def Cval(x):
            hh = unpack(x)
            c = np.convolve(hh, hh)
            return 2.0 * N * c.max()

        def Cval_smooth(x, beta):
            hh = unpack(x)
            c = np.convolve(hh, hh)
            m = c.max()
            w = np.exp(beta * (c - m))
            sm = (c * w).sum() / w.sum()
            return 2.0 * N * sm

        best = h.copy()
        bestC = Cval(np.log(h + 1e-12))
        x = np.log(h + 1e-12)

        betas = [beta_scale, beta_scale * 5, beta_scale * 25, beta_scale * 125]
        for beta in betas:
            if time.process_time() >= end_time:
                break
            def f(xx):
                return Cval_smooth(xx, beta)
            try:
                res = minimize(f, x, method='L-BFGS-B',
                               options={'maxiter': 200, 'ftol': 1e-14, 'gtol': 1e-12})
                x = res.x
            except Exception:
                break
            cand = unpack(x)
            cc = Cval(x)
            if cc < bestC:
                bestC = cc
                best = cand.copy()
        return best, bestC

    def polish(h, end_time):
        h = np.maximum(np.asarray(h, dtype=float), 0.0)
        s = h.sum()
        if s <= 0:
            return np.ones(len(h)), np.inf
        h = h / s
        N = len(h)
        conv = np.convolve(h, h)
        bestC = 2.0 * N * conv.max()
        best = h.copy()

        def try_update(h, conv, s, i, nv):
            old = h[i]
            d = nv - old
            if d == 0.0 or nv < 0:
                return None
            sc = s + d
            if sc <= 0:
                return None
            c = conv.copy()
            a = 2.0 * d
            end = min(i + N, 2 * N - 1)
            c[i:end] += a * h[0:end - i]
            c[2 * i] += d * d
            M = c.max()
            return (2.0 * N * M / (sc * sc), c, sc, nv)

        for scale in (0.05, 0.02, 0.01, 0.005, 0.002, 0.001, 5e-4, 2e-4, 1e-4,
                      5e-5, 2e-5, 1e-5, 5e-6, 2e-6, 1e-6, 5e-7, 1e-7):
            if time.process_time() >= end_time:
                break
            improved = True
            while improved and time.process_time() < end_time:
                improved = False
                M = conv.max()
                active = np.where(conv >= M * (1.0 - 1e-4))[0]
                cand = np.zeros(N, dtype=bool)
                for k in active:
                    lo = max(0, k - (N - 1))
                    hi = min(N - 1, k)
                    cand[lo:hi + 1] = True
                order = np.where(cand)[0]
                for i in order:
                    if time.process_time() >= end_time:
                        break
                    old = h[i]
                    best_res = None
                    for f in (1.0 + scale, 1.0 - scale, 1.0 + 0.5 * scale, 1.0 - 0.5 * scale):
                        nv = old * f
                        r = try_update(h, conv, s, i, nv)
                        if r is not None and r[0] < bestC - 1e-16:
                            if best_res is None or r[0] < best_res[0]:
                                best_res = r
                    for d in (scale * 0.01, -scale * 0.01):
                        nv = max(0.0, old + d)
                        r = try_update(h, conv, s, i, nv)
                        if r is not None and r[0] < bestC - 1e-16:
                            if best_res is None or r[0] < best_res[0]:
                                best_res = r
                    if best_res is not None:
                        bestC, conv, s, nv = best_res
                        h[i] = nv
                        best = h.copy()
                        improved = True
        return best, bestC

    N0 = len(h0)
    # Focus on the start's N (it scored well) plus a few alternatives
    candidates = set([N0])
    for dN in (-1, 1, 2, -2, 3, -3):
        n = N0 + dN
        if 4 <= n <= 30000:
            candidates.add(n)
    candidates = sorted(candidates)

    scored = []
    for n in candidates:
        hc = resample(h0, n) if n != N0 else h0.copy()
        if hc.sum() <= 0:
            continue
        hc = hc / hc.sum()
        c = C_of(hc)
        scored.append((c, n, hc))
    scored.sort(key=lambda x: x[0])

    if not scored:
        return np.asarray(h0, dtype=float)

    best_overall = None
    best_overall_C = np.inf

    # Spend most of the budget on the best candidate (its N), then polish
    for k, (c0, n, hc) in enumerate(scored[:1]):
        now = time.process_time()
        if now >= deadline - 0.05:
            break
        end_t = deadline
        h_opt, c_opt = exact_descent(hc, min(end_t, now + 0.3 * (end_t - now)))
        h_opt, c_opt = optimize_smooth(h_opt, min(end_t, now + 0.6 * (end_t - now)))
        h_opt, c_opt = exact_descent(h_opt, end_t, rounds=100)
        h_opt, c_opt = polish(h_opt, end_t)
        c_opt = C_of(h_opt)
        if c_opt < best_overall_C:
            best_overall_C = c_opt
            best_overall = h_opt.copy()

    if best_overall is None:
        best_overall = h0
        best_overall_C = C_of(h0)

    now = time.process_time()
    if now < deadline - 0.05:
        h_fin, c_fin = exact_descent(best_overall, (now + deadline) / 2, rounds=150)
        h_fin, c_fin = polish(h_fin, deadline)
        c_fin = C_of(h_fin)
        if c_fin < best_overall_C:
            best_overall = h_fin
            best_overall_C = c_fin

    return np.asarray(best_overall, dtype=float)
